from sprint_common import *
OUT=HERE/'sprint-02'
OUT.mkdir(exist_ok=True)
inventory=json.loads((HERE/'screen-inventory.json').read_text())
planned=sorted([r for r in inventory['screens'] if r.get('sprint')==2],key=lambda x:x['proposalId'])
assert len(planned)==20 and planned[-1]['file']=='add_property_photos_page.dart'
screens=[]
def variant(content,footer_html=''):return {'content':content,'footer':footer_html}
def add(n,name,english,body,behavior,states,deps=(),refs=(),group='الحساب',back='S26',foot='',variants=None,hero=None,chrome='standard'):
    record=planned[n-41];assert record['proposalId']==f'S{n}'
    s=dict(id=f'S{n}',name=name,english=english,group=group,back=back,content=body,footer=foot,behavior=behavior,requiredStates=states,dependencies=[source(x) for x in deps],visualReference=list(refs),variants=variants or {},chrome=chrome)
    s.update(source(record['file']))
    if hero:s['hero']=hero
    screens.append(s)

def stat(value,label):return f'<div class="stat"><b>{value}</b><small>{label}</small></div>'
def status_body(title,sub,symbol='shield'):return intro(title,sub,True,symbol)
def blank(title,sub='ستظهر البيانات المتاحة لحسابك هنا.'):return status_body(title,sub,'file')
def view_document(kind='terms'):
    heading={'terms':'الشروط والأحكام','privacy':'سياسة الخصوصية','about':'عن سكون'}[kind]
    text={'terms':[('استخدام الخدمة','تعرّف على ضوابط استخدام سكون ومسؤولياتك أثناء الرحلة.'),('الحساب والتواصل','راجع قواعد إدارة حسابك والتواصل عبر المنصة.'),('الطلبات والاتفاقات','اطّلع على الشروط ذات الصلة بطلباتك واتفاقات الإيجار.')], 'privacy':[('بيانات الحساب','كيف تُستخدم البيانات اللازمة لتقديم الخدمة.'),('التحكم والاختيارات','تعرّف على اختيارات الخصوصية المتاحة لك.'),('التواصل والدعم','اطّلع على طريقة التواصل بشأن بياناتك.')], 'about':[('سكنك، على راحتك.','رحلة تجمع البحث والتواصل والمتابعة في مكان واحد.'),('من أول بحث لحد الاتفاق','تجربة واضحة تربطك بالخطوة اللي بعدها.')]}[kind]
    return (mark() if kind=='about' else '')+intro(heading,'مثال نصي لعرض التصميم · ليس نصًا معتمدًا')+''.join(f'<section class="document-section"><h3>{h}</h3><p>{p}</p></section>' for h,p in text)

def map_art(picker=False):
    # An intentionally schematic offline map, not a geographically accurate basemap.
    streets='<path d="M-10 100 330 180M-5 230 350 290M80 -10 15 380M210 -10 150 380M315 -10 255 380"/>'
    land='<path d="M10 24h95v65H10zM150 20h120v90H150zM160 220h105v90H160z"/>'
    pins=button('٨٬٥٠٠',action='map-marker',kind='price-pin selected',extra='data-marker="0" style="top:41%;right:21%"')+button('٦٬٠٠٠',action='map-marker',kind='price-pin',extra='data-marker="1" style="top:66%;right:61%"') if not picker else '<span class="location-pin" aria-hidden="true">'+icon('pin')+'</span>'
    return f'<div class="map-stage {"picker-map" if picker else ""}" {"data-pick-map tabindex=0 role=button aria-label=اختيار-موقع-توضيحي" if picker else ""}><svg class="schematic-map" viewBox="0 0 330 350" preserveAspectRatio="none" aria-hidden="true"><rect width="330" height="350" class="map-land"/><g class="map-parks">{land}</g><path class="map-water" d="M0 0h38l50 350H0Z"/><g class="map-roads">{streets}</g></svg><span class="map-place">المعادي</span><span class="map-disclaimer">رسم توضيحي للخريطة</span>{pins}</div>'

