def ticket_form(feedback=False,payment=False):
    topics=[('visit','معاينة'),('payment','الدفع'),('verification','توثيق الهوية'),('report_owner','بلاغ عن مالك'),('property','عقار'),('other','أخرى')]
    form=intro('خلّينا نساعدك.','احكي لنا المشكلة، وخلي تفاصيلها واضحة.' if not feedback else 'شاركنا اقتراحك لتحسين سكون.')
    form+='<form id="ticket-form" data-form="ticket">'+chips(topics,'support-topic',1 if payment else 5 if feedback else 0)
    form+='<div class="payment-context" data-payment-context '+('' if payment else 'hidden')+'><label class="field"><span>تفاصيل مشكلة الدفع</span><select name="paymentIssue"><option value="">مشكلة عامة</option><option value="off_platform_request">طُلب مني الدفع خارج المنصة</option><option value="off_platform_payment">دفعت خارج المنصة</option></select></label></div>'
    form+=field('عنوان الطلب','subject',hint='وصف مختصر للمشكلة',extra='required minlength="3" maxlength="160"')+textarea('التفاصيل','description',hint='اكتب التفاصيل اللي تساعدنا نفهم المشكلة…',extra='required minlength="10" maxlength="4000" rows="4"')+button(icon('plus')+' إرفاق عينة صورة',action='ticket-attachment',kind='secondary wide')+'<div class="sample-attachments" aria-live="polite"></div></form>'
    return form
support_footer='<footer class="actions"><button class="primary" type="submit" form="ticket-form">إرسال الطلب</button></footer>'
unknown_ticket=note('لسه مش متأكدين إن الطلب اتسجل. راجع حالته قبل ما تحاول إرساله مرة تانية.','warning','clock')+ticket_form().replace('<form id="ticket-form" data-form="ticket">','<form id="ticket-form" data-form="ticket"><fieldset disabled class="uncertain-fields">').replace('</form>','</fieldset></form>')
