def visit_content(status='pending'):
    words={'pending':('بانتظار المالك','warning','طلبك في انتظار الموافقة.'),'confirmed':('مؤكدة','','المالك وافق على موعد المعاينة.'),'completed':('مكتملة','','شارك تجربتك بعد المعاينة.'),'cancelled':('ملغاة','error','تقدر تبدأ البحث عن بديل.')}
    title,kind,sub=words[status]
    content=status_body(title,sub,'calendar')+compact_property()+summary([('اليوم','الثلاثاء ٢٧ أكتوبر'),('الوقت','٦:٠٠ مساءً'),('المالك','محمد أحمد')])+note('تواصلك الآمن داخل سكون. أرقام التواصل تظهر فقط لو كانت متاحة ومصرّح بها.')
    if status in ['pending','confirmed']:content+=button('تواصل مع المالك',action='visit-chat',kind='primary wide')+button('إلغاء الطلب' if status=='pending' else 'إلغاء المعاينة',action='cancel-visit',kind='danger-text wide')
    if status=='confirmed':content+=button('تعديل الموعد',action='reschedule-visit',kind='secondary wide')+button('إضافة للتقويم',action='visit-calendar',kind='textbtn wide')
    if status=='completed':content+=button('قيّم تجربتك',action='visit-review',kind='primary wide')
    if status=='cancelled':content+=button('ابحث عن بديل',to='S56',kind='primary wide')
    return content
add(57,'تفاصيل المعاينة','Tenant viewing detail',visit_content(),
 'Fresh authoritative details gate cancel/review/reschedule/reassign. Pending remains awaiting owner, not confirmed. Cancellation requires confirmation and successful server result, then returns updated visit. CanChat starts context-aware conversation; canReview opens ReviewsHub, and contact permission refreshes on return/resume. Calendar export only when VisitCalendarData can build an event. Cached data cannot trigger mutating actions. Owner phone is never invented or exposed.', ['pending','confirmed','completed','cancelled','loading','error','stale','restricted-contact'],['visit_details_content.dart','visit_details_actions.dart','visit_details_extra.dart','visit_calendar_button.dart'],['S11','S12','S19'],group='المعاينات',back='S12',variants={'confirmed':variant(visit_content('confirmed')),'completed':variant(visit_content('completed')),'cancelled':variant(visit_content('cancelled')),'stale':variant(note('دي آخر بيانات محفوظة. حدّث التفاصيل قبل اتخاذ إجراء.','warning','clock')+compact_property()+summary([('حالة آخر تحميل','بانتظار المالك')])+button('تحديث البيانات',action='reset-state',kind='secondary wide'))})
