add(60,'إضافة العقار · الصور','Property creation: media step',photos,
 'Photos step is distinct from original S17 basics. Current validator requires 10–25 nonduplicate photos AND ready video (1–60s); video preparation blocks next. Keep main selection, reorder/replace/delete, names/descriptions, virtual-tour-later checkbox and partial-offering accommodation media. This is step 2 of 3, not publish. Demo thumbnails reuse bundled artwork for visual layout only; no real media validation/upload occurs. Next opens later planned pricing step explanation.', ['ready','empty','duplicate','preparing','video-missing','permission-denied','partial-offering','error'],['add_property_photos_page.dart','property_form_validation.dart','property_photo_grid.dart','property_video_picker.dart','rental_accommodation_media_section.dart','validators.dart'],['S17','S08'],group='المالك',back='S17',foot=footer('التالي: التسعير','media-next'),variants={'preparing':variant(note('جار تجهيز الفيديو. انتظر قبل المتابعة.','info','clock')+photos,footer('جار تجهيز الفيديو…','media-next',extra='disabled')),'duplicate':variant(note('في صور مكررة. استبدل الصور المكررة قبل المتابعة.','error','camera')+photos,footer('التالي: التسعير','media-next',extra='disabled')),'partial-offering':variant(photos+section('صور وحدات الإقامة',row('غرفة ١','صور ووصف خاص بالجزء المعروض',action='accommodation-media',symbol='camera')),footer('التالي: التسعير','media-next'))})
